from fractions import Fraction as F
import json
rows=[('A',5,(0,0,0,1)),('A',6,(1,0,1,0)),('B',11,(0,0,0,1)),('B',5,(0,1,1,0)),('C',6,(0,1,0,1)),('C',4,(1,0,1,1)),('D',6,(0,0,1,0)),('D',8,(1,1,0,0))]
tests='TUVW'
cost=dict(zip(tests,[F(1),F(1),F(17,10),F(21,10)]))
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def stop(ids):
    w=sum(rows[i][1] for i in ids)
    return min((sum(F(rows[i][1],w)*loss[a]['ABCD'.index(rows[i][0])] for i in ids),'ABCD'[a]) for a in range(4))
def solve(ids,available,remaining):
    best,act=stop(ids)
    vals={'STOP':best}
    w=sum(rows[i][1] for i in ids)
    if remaining:
        for t in available:
            j=tests.index(t)
            value=cost[t]
            for b in (0,1):
                branch=tuple(i for i in ids if rows[i][2][j]==b)
                if branch:
                    v,_,_=solve(branch,tuple(x for x in available if x!=t),remaining-1)
                    value+=F(sum(rows[i][1] for i in branch),w)*v
            vals[t]=value
            if value<best:
                best,act=value,t
    return best,act,vals
ids=tuple(range(8))
value,first,vals=solve(ids,tuple(tests),2)
nxt={}
if first in tests:
    for b in (0,1):
        branch=tuple(i for i in ids if rows[i][2][tests.index(first)]==b)
        nxt[str(b)]=solve(branch,tuple(t for t in tests if t!=first),1)[1] if branch else 'IMPOSSIBLE'
artifact={'first':first,'first_losses':{k:float(v) for k,v in vals.items()},'next':nxt}
payload=json.dumps(artifact)
decoded=json.loads(payload)
assert set(decoded)=={'first','first_losses','next'}
assert set(decoded['first_losses'])=={'STOP','T','U','V','W'}
# Independent unnormalized, exhaustive two-stage policy evaluation.
total=sum(r[1] for r in rows)
def raw_stop(sub):
    return min(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in sub) for a in range(4))
ind={'STOP':F(raw_stop(ids),total)}
for t in tests:
    raw=cost[t]*total
    for b in (0,1):
        sub=[i for i in ids if rows[i][2][tests.index(t)]==b]
        if not sub: continue
        opts=[raw_stop(sub)]
        for u in tests:
            if u==t: continue
            opts.append(cost[u]*sum(rows[i][1] for i in sub)+sum(raw_stop([i for i in sub if rows[i][2][tests.index(u)]==c]) for c in (0,1)))
        raw+=min(opts)
    ind[t]=raw/total
assert all(abs(decoded['first_losses'][k]-float(v))<1e-10 for k,v in ind.items())
assert decoded['first']==min(ind,key=ind.get)
print(payload)
print('Verified independently:', {k:str(v) for k,v in ind.items()})
print('Next actions verified:',nxt)

