from fractions import Fraction as F
import json
rows=[('A',5,(0,0,0,1)),('A',6,(1,0,1,0)),('B',11,(0,0,0,1)),('B',5,(0,1,1,0)),('C',6,(0,1,0,1)),('C',4,(1,0,1,1)),('D',6,(0,0,1,0)),('D',8,(1,1,0,0))]
modes='ABCD'; tests='TUVW'
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
cost={'T':F(7),'V':F(17,10),'W':F(21,10)}
def entry():
    sub=[r for r in rows if r[2][1]==0]
    total=sum(r[1] for r in sub)
    posterior={a:float(F(sum(r[1] for r in sub if r[0]==a),total)) for a in modes}
    def repair(rs):
        return min((sum(r[1]*loss[i][modes.index(r[0])] for r in rs),a) for i,a in enumerate(modes))
    vals={a:F(sum(r[1]*loss[i][modes.index(r[0])] for r in sub),total) for i,a in enumerate(modes)}
    branches={}
    for t in cost:
        parts=[[r for r in sub if r[2][tests.index(t)]==b] for b in (0,1)]
        vals[t]=cost[t]+sum(F(repair(p)[0],total) for p in parts)
        branches[t]={str(b):repair(p)[1] if p else 'IMPOSSIBLE' for b,p in enumerate(parts)}
    act=min(vals,key=vals.get)
    return {'posterior':posterior,'remaining_losses':{a:float(v) for a,v in vals.items()},'action':act,'repair_after':branches.get(act,{})}
payload=json.dumps(entry())
d=json.loads(payload)
# Independent expected values from U=0 row weights: A=11 B=11 C=4 D=6, total 32.
assert d['posterior']=={'A':11/32,'B':11/32,'C':4/32,'D':6/32}
expected={'A':243/32,'B':231/32,'C':466/32,'D':250/32,
          'T':7+150/32,'V':1.7+177/32,'W':2.1+174/32}
assert all(abs(d['remaining_losses'][k]-v)<1e-10 for k,v in expected.items())
assert d['action']=='W'
assert d['repair_after']=={'0':'D','1':'B'}
# Faulty outdated T price would instead select T; distinguish the update.
faulty=dict(expected); faulty['T']=1+150/32
assert min(faulty,key=faulty.get)=='T' and min(expected,key=expected.get)=='W'
assert set(d)=={'posterior','remaining_losses','action','repair_after'}
print(payload)

