def entry():
    rows=[(0,5,(0,0,1)),(0,6,(1,1,0)),(1,11,(0,0,1)),(2,4,(1,1,1)),(3,6,(0,1,0))]
    L=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
    repairs='ABCD'
    def best(rs):
        return min((sum(w*L[a][m] for m,w,r in rs),repairs[a]) for a in range(4))
    values={repairs[a]:F(sum(w*L[a][m] for m,w,r in rows),32) for a in range(4)}
    branches={}
    for j,(t,c) in enumerate([('T',F(7)),('V',F(17,10)),('W',F(21,10))]):
        groups=[[row for row in rows if row[2][j]==b] for b in (0,1)]
        values[t]=c+sum(F(best(g)[0],32) for g in groups)
        branches[t]={str(b):best(g)[1] if g else 'IMPOSSIBLE' for b,g in enumerate(groups)}
    action=min(values,key=values.get)
    return {'posterior':{repairs[m]:sum(w for mm,w,r in rows if mm==m)/32 for m in range(4)},'remaining_losses':{k:float(v) for k,v in values.items()},'action':action,'repair_after':branches.get(action,{})}
payload=json.dumps(entry()); d=json.loads(payload)
expected={'A':243/32,'B':231/32,'C':466/32,'D':250/32,'T':7+141/32,'V':1.7+159/32,'W':2.1+195/32}
assert all(abs(d['remaining_losses'][k]-v)<1e-10 for k,v in expected.items())
assert d['posterior']=={'A':11/32,'B':11/32,'C':4/32,'D':6/32}
assert d['action']=='V' and d['repair_after']=={'0':'B','1':'D'}
faulty=dict(expected); faulty['T']=1+141/32
assert min(faulty,key=faulty.get)=='T'
print(payload)

